const raw = $json.request_id ? $json : (($json.body && $json.body.request_id) ? $json.body : $json);

function errorResult(code, message) {
  return [{
    json: {
      adapter_status: "error",
      component_id: "ADP-GDRIVE",
      component_version: "v1",
      request_id: raw.request_id || null,
      source_component: raw.source_component || null,
      provider: "google_drive",
      operation: "upload_file",
      validation_status: "invalid",
      source_file_id: raw.file?.file_id || null,
      drive_file: null,
      manual_review_required: true,
      error_code: code,
      error_message: message,
      next_action: "route_to_manual_review_or_error_log",
      status_log_event: "gdrive_upload_validation_error",
      downstream_components: ["C5-E", "C6-G", "C5-W"],
      source_result: null,
      original_input: raw
    }
  }];
}

if (!raw.request_id) return errorResult("MISSING_REQUEST_ID", "request_id is required.");
if (!raw.file || typeof raw.file !== "object") return errorResult("MISSING_FILE_OBJECT", "file object is required.");
if (!raw.drive || typeof raw.drive !== "object") return errorResult("MISSING_DRIVE_OBJECT", "drive object is required.");

const file = raw.file;
const drive = raw.drive;

const fileId = String(file.file_id || "").trim();
const filename = String(file.filename || "").trim();
const mimeType = String(file.mime_type || "").trim();
const extension = String(file.extension || "").trim();
const sizeBytes = Number(file.size_bytes || 0);
const binaryPropertyName = String(file.binary_property_name || "data").trim();
const folderId = String(drive.destination_folder_id || "").trim();
const pathLabel = String(drive.destination_path_label || "").trim();

if (!fileId) return errorResult("MISSING_SOURCE_FILE_ID", "file.file_id is required.");
if (!filename) return errorResult("MISSING_FILENAME", "file.filename is required.");
if (!mimeType) return errorResult("MISSING_MIME_TYPE", "file.mime_type is required.");
if (!binaryPropertyName) return errorResult("MISSING_BINARY_PROPERTY", "file.binary_property_name is required.");
if (!folderId || folderId === "configured_manually_in_n8n") return errorResult("MISSING_DESTINATION_FOLDER", "drive.destination_folder_id must be set to a real Google Drive folder ID.");

const testContent = raw.metadata?.test_content || `ADP-GDRIVE test upload\nrequest_id=${raw.request_id}\nfilename=${filename}\n`;

const item = {
  json: {
    adapter_status: "ready",
    component_id: "ADP-GDRIVE",
    component_version: "v1",
    request_id: raw.request_id,
    source_component: raw.source_component || null,
    provider: "google_drive",
    operation: "upload_file",
    validation_status: "valid",
    source_file_id: fileId,
    drive_upload: {
      filename,
      mime_type: mimeType,
      extension,
      size_bytes: sizeBytes,
      source_url: file.source_url || null,
      storage_provider: file.storage_provider || null,
      binary_property_name: binaryPropertyName,
      destination_folder_id: folderId,
      destination_path_label: pathLabel,
      overwrite_existing: Boolean(drive.overwrite_existing)
    },
    routing_options: raw.routing_options || {},
    metadata: raw.metadata || {},
    manual_review_required: false,
    error_code: null,
    error_message: null,
    next_action: "execute_gdrive_upload",
    status_log_event: "gdrive_upload_request_validated",
    original_input: raw
  },
  binary: {}
};

const incomingBinary = $binary && $binary[binaryPropertyName] ? $binary[binaryPropertyName] : null;

if (incomingBinary) {
  item.binary[binaryPropertyName] = incomingBinary;
} else {
  item.binary[binaryPropertyName] = {
    data: Buffer.from(testContent, "utf8").toString("base64"),
    mimeType,
    fileName: filename
  };
}

return [item];

const validation = $node["Normalize And Validate Google Drive Upload Request"].json;
const providerResult = $json;

const hasError = Boolean(providerResult.error || providerResult.statusCode >= 400 || providerResult.message?.includes?.("ERROR"));

if (hasError) {
  return [{
    json: {
      adapter_status: "error",
      component_id: "ADP-GDRIVE",
      component_version: "v1",
      request_id: validation.request_id || null,
      source_component: validation.source_component || null,
      provider: "google_drive",
      operation: "upload_file",
      validation_status: validation.validation_status || "valid",
      source_file_id: validation.source_file_id || null,
      drive_file: null,
      manual_review_required: true,
      error_code: "GDRIVE_UPLOAD_FAILED",
      error_message: providerResult.error?.message || providerResult.message || "Google Drive upload failed.",
      next_action: "route_to_manual_review_or_error_log",
      status_log_event: "gdrive_upload_failed",
      downstream_components: ["C5-E", "C6-G", "C5-W"],
      source_result: providerResult,
      original_input: validation.original_input || null
    }
  }];
}

return [{
  json: {
    adapter_status: "success",
    component_id: "ADP-GDRIVE",
    component_version: "v1",
    request_id: validation.request_id || null,
    source_component: validation.source_component || null,
    provider: "google_drive",
    operation: "upload_file",
    validation_status: "valid",
    source_file_id: validation.source_file_id || null,
    drive_file: {
      id: providerResult.id || providerResult.fileId || null,
      name: providerResult.name || validation.drive_upload?.filename || null,
      mime_type: providerResult.mimeType || validation.drive_upload?.mime_type || null,
      web_view_link: providerResult.webViewLink || providerResult.webContentLink || null,
      folder_id: validation.drive_upload?.destination_folder_id || null
    },
    manual_review_required: false,
    error_code: null,
    error_message: null,
    next_action: validation.routing_options?.on_success || "log_status",
    status_log_event: "gdrive_upload_success",
    downstream_components: ["C5-W"],
    source_result: providerResult,
    original_input: validation.original_input || null
  }
}];
